"""Independent geometry and periodicity checks for the wallpaper utility."""

import random
import unittest

from src.component import calculate_black_area_doubled


def geometric_cell_area_doubled(x: int, y: int) -> int:
    """Integrate a unit cell using four triangle-interior sample points."""
    # Both diagonals divide a square into four equal-area triangles. Each
    # wallpaper boundary is a square edge or one of these diagonals, so the
    # color is constant inside each triangle. Offsets are scaled by six.
    samples = ((3, 1), (5, 3), (3, 5), (1, 3))
    black_count = 0
    for dx, dy in samples:
        crossings = x + (6 * y + dy) // 12 + (6 * (x + y) + dx + dy) // 12
        black_count += crossings % 2 == 0
    assert black_count % 2 == 0
    return black_count // 2


class WallpaperTests(unittest.TestCase):
    def test_small_rectangles_against_geometry(self):
        cells = {
            (x, y): geometric_cell_area_doubled(x, y)
            for x in range(-8, 8)
            for y in range(-8, 8)
        }
        for a in range(-8, 8):
            for b in range(-8, 8):
                for c in range(a + 1, 9):
                    for d in range(b + 1, 9):
                        expected = sum(
                            cells[x, y]
                            for x in range(a, c)
                            for y in range(b, d)
                        )
                        self.assertEqual(
                            calculate_black_area_doubled(a, b, c, d), expected,
                            (a, b, c, d),
                        )

    def test_large_coordinates_against_geometry(self):
        rng = random.Random(2025)
        for _ in range(2000):
            a = rng.randint(-10**9, 10**9 - 10)
            b = rng.randint(-10**9, 10**9 - 10)
            c = a + rng.randint(1, 10)
            d = b + rng.randint(1, 10)
            expected = sum(
                geometric_cell_area_doubled(x, y)
                for x in range(a, c)
                for y in range(b, d)
            )
            self.assertEqual(calculate_black_area_doubled(a, b, c, d), expected)

    def test_complete_horizontal_periods(self):
        # A complete horizontal period has doubled black area equal to its
        # width for every integer-height strip, regardless of the origin.
        a, b, c, d = -678601079, -990141434, 909949145, 506736933
        self.assertEqual((c - a) % 4, 0)
        self.assertEqual(
            calculate_black_area_doubled(a, b, c, d), (c - a) * (d - b)
        )

    def test_maximum_rectangle(self):
        self.assertEqual(
            calculate_black_area_doubled(-10**9, -10**9, 10**9, 10**9),
            4 * 10**18,
        )


if __name__ == '__main__':
    unittest.main()
